if isinstance(d, dict):
    keys = [k for k in d.keys() if 'invoice' in k.lower() or 'payment' in k.lower() or 'item' in k.lower()]
    print("invoice-ish keys:", keys[:30])
    # search nested for invoice
    def walk(o, path=""):
        hits = []
        if isinstance(o, dict):
            for k,v in o.items():
                if 'invoice' in str(k).lower():
                    hits.append(path + "/" + str(k))
                hits += walk(v, path + "/" + str(k))
        elif isinstance(o, list):
            for i,v in enumerate(o):
                hits += walk(v, path + f"[{i}]")
        return hits
    hits = walk(d)
    print("nested invoice hits:", len(hits))
    for h in hits[:40]: print(" ", h)
EOF

