def norm_paths(p):
    out = {}
    for path, item in p.items():
        if 'invoice' not in path: continue
        for method, op in item.items():
            if isinstance(op, dict) and 'operationId' in op:
                key = (path, method)
                out[key] = {
                    'operationId': op.get('operationId'),
                    'params': [(q.get('name'), q.get('in'), q.get('required'), (q.get('schema') or {}).get('type')) for q in op.get('parameters', [])],
